spec.setup_code:
function rng(seed){var a=seed;return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
var R=rng(7);
function gauss(){var u=Math.max(R(),1e-6),v=R();return Math.sqrt(-2*Math.log(u))*Math.cos(6.2831853*v);}
var NC=3,N=120,SEG=20,STEPS=20;
var atoms=[];
var chainOff=[],segOff=[];
for(var c=0;c<NC;c++){chainOff.push([gauss(),gauss(),gauss()]);}
for(var c=0;c<NC;c++){
  var a0=c*2*Math.PI/NC;
  for(var i=0;i<N;i++){
    var u=i/(N-1);
    var rbd=u>=0.8;
    var r=0.18+0.5*Math.pow(u,0.8)+(rbd?0.14:0);
    var ang=a0+0.9*u+0.22*Math.sin(u*16);
    var z=-1+1.7*u;
    var x0=r*Math.cos(ang)+0.05*Math.cos(i*1.9);
    var y0=r*Math.sin(ang)+0.05*Math.sin(i*1.9);
    var z0=z+0.04*Math.sin(i*2.7);
    var sg=Math.floor(i/SEG);
    if(!segOff[c*10+sg])segOff[c*10+sg]=[gauss(),gauss(),gauss()];
    atoms.push({c:c,i:i,rbd:rbd,t:[x0,y0,z0],e:[gauss(),gauss(),gauss()],g:chainOff[c],s:segOff[c*10+sg]});
  }
}
function sigmaAt(s){return Math.pow(1-s,2.0);}
function ease(x){return x*x*(3-2*x);}
function clamp(x,a,b){return Math.max(a,Math.min(b,x));}
var P=[];
for(var k=0;k<atoms.length;k++)P.push([0,0,0,0]);
function draw(ctx,width,height,time,dt){
  ctx.fillStyle="#ffffff";ctx.fillRect(0,0,width,height);
  var period=9;
  var tt=time%period;
  var tStart=0.6,tEnd=7.2;
  var p=clamp((tt-tStart)/(tEnd-tStart),0,1);
  var kf=p*STEPS;
  var k=Math.min(STEPS,Math.floor(kf));
  var fr=kf-Math.floor(kf);
  var sNow=(k+ease(clamp(fr/0.5,0,1)))/STEPS;
  if(p>=1)sNow=1;
  var sig=sigmaAt(sNow);
  var gScale=clamp((sig-0.12)/0.88,0,1);
  var lScale=sig;
  var stepShown=p>=1?STEPS:k;
  // layout
  var lw=width*0.62;
  var cx=lw*0.5,cy=height*0.5+8;
  var S=Math.min(lw*0.42,height*0.30);
  var rot=0.5+time*0.35;
  var cr=Math.cos(rot),sr=Math.sin(rot);
  var tilt=0.35,ct=Math.cos(tilt),st=Math.sin(tilt);
  ctx.font="13px sans-serif";ctx.textBaseline="alphabetic";
  ctx.fillStyle="#1a1a1d";ctx.textAlign="left";
  ctx.fillText("Diffusion module: xₜ₋₁ = Dθ(xₜ, σₜ | s, z)",12,20);
  for(var n=0;n<atoms.length;n++){
    var a=atoms[n];
    var x=a.t[0]+gScale*(1.1*a.g[0]+0.45*a.s[0])+lScale*0.5*a.e[0];
    var y=a.t[1]+gScale*(1.1*a.g[1]+0.45*a.s[1])+lScale*0.5*a.e[1];
    var z=a.t[2]+gScale*(0.9*a.g[2]+0.45*a.s[2])+lScale*0.5*a.e[2];
    var xr=x*cr+y*sr, yr=-x*sr+y*cr;
    var y2=yr*ct-z*st, z2=yr*st+z*ct;
    var per=1/(1+0.18*z2);
    P[n][0]=cx+xr*S*per;P[n][1]=cy-y2*S*per*0+(-z*ct-yr*st)*S*per*(1)*0+cy*0;
    P[n][1]=cy-(z*ct+yr*st)*S*per;
    P[n][2]=yr*ct-z*st;
    P[n][3]=per;
  }
  // bonds
  ctx.lineWidth=1.2;
  var bondOK=1-clamp(sig/0.35,0,1);
  for(var c=0;c<NC;c++){
    for(var i=1;i<N;i++){
      var n=c*N+i;
      ctx.strokeStyle=atoms[n].rbd?"rgba(225,29,72,"+(0.15+0.5*bondOK)+")":"rgba(26,26,29,"+(0.08+0.4*bondOK)+")";
      ctx.beginPath();ctx.moveTo(P[n-1][0],P[n-1][1]);ctx.lineTo(P[n][0],P[n][1]);ctx.stroke();
    }
  }
  var cols=["#7c3aed","#0284c7","#059669"];
  for(var n=0;n<atoms.length;n++){
    var a=atoms[n];
    ctx.globalAlpha=0.55+0.4*clamp(0.5+P[n][2]*0.5,0,1);
    ctx.fillStyle=a.rbd?"#e11d48":cols[a.c];
    ctx.beginPath();ctx.arc(P[n][0],P[n][1],(a.rbd?3.2:2.4)*P[n][3],0,6.2832);ctx.fill();
  }
  ctx.globalAlpha=1;
  // legend
  var lx=12,ly=height-64;
  ctx.font="12px sans-serif";
  for(var c=0;c<3;c++){ctx.fillStyle=cols[c];ctx.beginPath();ctx.arc(lx+5+c*60,ly,4,0,6.2832);ctx.fill();ctx.fillStyle="#1a1a1d";ctx.fillText("chain "+"ABC".charAt(c),lx+14+c*60,ly+4);}
  ctx.fillStyle="#e11d48";ctx.beginPath();ctx.arc(lx+5,ly+18,4,0,6.2832);ctx.fill();
  ctx.fillStyle="#1a1a1d";ctx.fillText("RBD (receptor-binding domain)",lx+14,ly+22);
  ctx.fillText("Schematic trimer inspired by 6VXX (closed spike)",lx,ly+40);
  // right panel
  var px=lw+10,pw=width-lw-24,py=50,ph=height*0.36;
  ctx.strokeStyle="#1a1a1d";ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px,py+ph);ctx.lineTo(px+pw,py+ph);ctx.stroke();
  ctx.fillStyle="#1a1a1d";ctx.textAlign="left";
  ctx.fillText("σ",px-2,py-8);
  ctx.textAlign="right";ctx.fillText("step",px+pw,py+ph+16);
  ctx.textAlign="left";
  ctx.fillStyle="rgba(124,58,237,0.10)";ctx.fillRect(px+1,py,pw*0.5,ph-1);
  ctx.fillStyle="rgba(5,150,105,0.10)";ctx.fillRect(px+pw*0.5,py,pw*0.5,ph-1);
  ctx.font="11px sans-serif";
  ctx.fillStyle="#7c3aed";ctx.fillText("high σ: global",px+4,py+12);
  ctx.fillStyle="#059669";ctx.fillText("low σ: local",px+pw*0.5+4,py+ph-6);
  ctx.strokeStyle="#0284c7";ctx.lineWidth=2;ctx.beginPath();
  for(var j=0;j<=40;j++){var s=j/40;var xx=px+s*pw,yy=py+ph-sigmaAt(s)*ph;if(j==0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy);}
  ctx.stroke();
  for(var j=0;j<=STEPS;j++){var s=j/STEPS;ctx.fillStyle=j<=stepShown?"#0284c7":"#cccccc";ctx.beginPath();ctx.arc(px+s*pw,py+ph-sigmaAt(s)*ph,2,0,6.2832);ctx.fill();}
  ctx.fillStyle="#e11d48";ctx.beginPath();ctx.arc(px+sNow*pw,py+ph-sig*ph,5,0,6.2832);ctx.fill();
  // conditioning boxes
  ctx.font="12px sans-serif";
  var by=py+ph+34;
  ctx.strokeStyle="#d97706";ctx.fillStyle="#1a1a1d";ctx.lineWidth=1.5;
  ctx.strokeRect(px,by,pw*0.45,24);ctx.strokeRect(px+pw*0.55,by,pw*0.45,24);
  ctx.textAlign="center";
  ctx.fillText("s (single)",px+pw*0.225,by+16);ctx.fillText("z (pair)",px+pw*0.775,by+16);
  ctx.strokeStyle="#d97706";ctx.beginPath();ctx.moveTo(px+pw*0.225,by+24);ctx.lineTo(px+pw*0.5,by+42);ctx.lineTo(px+pw*0.775,by+24);ctx.stroke();
  ctx.fillStyle="#d97706";ctx.fillText("condition each step",px+pw*0.5,by+58);
  // status
  ctx.textAlign="left";ctx.fillStyle="#1a1a1d";
  var phase=sig>0.45?"fixing global arrangement of chains":(sig>0.1?"refining domains and packing":"sharpening local stereochemistry");
  if(tt<tStart)phase="start: x_T = Gaussian noise";
  if(p>=1)phase="done: x₀ = predicted structure";
  ctx.fillText("step "+stepShown+" / "+STEPS+"   σ = "+sig.toFixed(2),12,height-12-0);
  ctx.fillStyle="#7c3aed";ctx.fillText(phase,12,40);
  return;
}
return {draw:draw};
